SELECT mpb.batch_number,mpb.pounds_u3o8 AS produced,COALESCE(SUM(us.pounds_shipped),0) AS shipped,mpb.pounds_u3o8-COALESCE(SUM(us.pounds_shipped),0) AS closing FROM mine_production_batch mpb JOIN legal_entity le ON le.id=mpb.entity_id LEFT JOIN uranium_shipment us ON us.production_batch_id=mpb.id AND us.generation_run_id=mpb.generation_run_id WHERE mpb.generation_run_id IN (:actual_run_id,:generation_run_id) AND le.code='RWH' GROUP BY mpb.id,mpb.batch_number,mpb.pounds_u3o8,mpb.production_date ORDER BY mpb.production_date,mpb.batch_number;
